const D = { energy: .5, scale: 1, density: .55, speed: 1, silt: .6, cloud: .5, hue: 40, x: .5, y: .55, style: 'landsat', act: 'ebb', seed: 0, alpha: 1 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const ho = P.hue - 40;
const L3 = (a, b, f) => [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f, a[2] + (b[2]-a[2])*f];
const sh = c => [hw(c[0] + ho), c[1], c[2]];

// ---------------- styles: five sensors looking at the same delta ----------------
const STY = {
  // true-colour satellite pass — ochre sediment, dark water, muted floodplain green
  landsat:    { land:[74,26,34], veg:[96,40,26], bar:[38,26,66], chan:[196,38,22], sea:[200,44,17],
                silt:[34,44,58], cloud:[40,4,96], shadow:[210,30,10], glint:[46,14,92], ramp:0, sound:0, grain:22 },
  // ABSTRACTED: 4-3-2 false colour — living vegetation burns red, water goes navy void
  falsecolor: { land:[344,44,32], veg:[352,74,58], bar:[188,20,72], chan:[232,74,14], sea:[236,80,10],
                silt:[184,52,64], cloud:[0,0,98], shadow:[240,40,8], glint:[186,30,94], ramp:0, sound:0, grain:14 },
  // ABSTRACTED: bathymetric chart — depth-banded ramp, soundings, no land texture
  bathy:      { land:[46,18,84], veg:[46,14,90], bar:[44,22,76], chan:[200,52,52], sea:[214,66,32],
                silt:[188,30,70], cloud:[0,0,99], shadow:[210,20,40], glint:[200,30,96], ramp:1, sound:1, grain:4 },
  // a peat-stained estuary under low cloud — near-monochrome, moody, the water is tea
  tannin:     { land:[38,30,27], veg:[54,26,22], bar:[34,24,48], chan:[24,52,17], sea:[22,56,14],
                silt:[28,44,34], cloud:[36,10,62], shadow:[20,30,6], glint:[38,18,72], ramp:0, sound:0, grain:30 },
  // a glacial outwash sandur — grey silt, black sand, milk-blue meltwater. Iceland from the air.
  ice:        { land:[210,10,24], veg:[196,12,30], bar:[204,8,52], chan:[186,30,68], sea:[196,26,40],
                silt:[190,18,74], cloud:[200,4,94], shadow:[212,24,14], glint:[188,10,96], ramp:0, sound:0, grain:26 }
};
const st = STY[P.style] || STY.landsat;

const en = Math.max(0, Math.min(1, P.energy));
const si = Math.max(0, Math.min(1, P.silt));
const cl = Math.max(0, Math.min(1, P.cloud));
const shoreY = height * P.y;                    // where the land gives way to open water
const key = width + 'x' + height + '|' + P.style + '|' + P.seed + '|' + Math.round(P.hue) + '|' + P.scale.toFixed(2) + '|' + P.density.toFixed(2) + '|' + P.y.toFixed(3) + '|' + P.x.toFixed(3);

// the braid corridor: a wandering centreline that fans out as it reaches the sea
const NT = Math.max(3, Math.round((5 + P.density * 9) / Math.max(.6, P.scale * .8)));   // thread count
const corr = yy => {
  const n = yy / Math.max(1, height);
  return width * P.x + (Math.sin(n * 3.3 + fr(1) * 6.3) * .13 + Math.sin(n * 7.9 + fr(2) * 6.3) * .05 + Math.sin(n * 1.6 + fr(3) * 6.3) * .09) * width;
};
const halfW = yy => { const n = Math.max(0, Math.min(1, yy / Math.max(1, shoreY))); return width * (.045 + .30 * Math.pow(n, 2.2)) * (.5 + P.scale * .6); };
// thread i's lateral offset — each wanders on its own incommensurate spatial frequency
const thread = (i, yy) => {
  const n = yy / Math.max(1, height);
  const base = (NT === 1) ? 0 : ((i / (NT - 1)) - .5) * 1.7;
  const w1 = Math.sin(n * (5.1 + i * 1.7) + fr(i * 7 + 11) * 6.3) * .42;
  const w2 = Math.sin(n * (11.3 + i * 2.3) + fr(i * 7 + 12) * 6.3) * .22;
  return corr(yy) + (base + w1 + w2) * halfW(yy);
};

if (!S.gnd || S.key !== key) {
  const W = Math.max(2, Math.ceil(width)), H = Math.max(2, Math.ceil(height));
  const mk = (w, h) => { const g = createGraphics(Math.max(2, Math.ceil(w)), Math.max(2, Math.ceil(h))); g.colorMode(g.HSB, 360, 100, 100, 100); return g; };
  if (S.gnd) { S.gnd.remove(); S.shad.remove(); S.cld.remove(); }
  // the cloud buffers are taller than the frame so a bounded vertical drift never opens an
  // edge gap — that lets them wrap in x ONLY (2 composites each, not a 2x2 = 4)
  const HB = H + u * .14;
  S.gnd = mk(W, H); S.shad = mk(W, HB); S.cld = mk(W, HB);

  const q = S.gnd; q.noStroke();
  const landC = sh(st.land), vegC = sh(st.veg), barC = sh(st.bar), chanC = sh(st.chan), seaC = sh(st.sea);

  // --- floodplain base + vegetation mottle: texture, never a flat green fill ---
  q.fill(landC[0], landC[1], landC[2]); q.rect(0, 0, W, shoreY + 2);
  if (!st.ramp) {
    for (let i = 0; i < 900; i++) {
      const mx = fr(i * 3 + 21) * W, my = fr(i * 3 + 22) * shoreY;
      const r = u * (.01 + fr(i * 3 + 23) * .05);
      const c = L3(landC, vegC, fr(i + 5));
      q.fill(c[0], c[1] * (.7 + fr(i) * .6), Math.max(2, c[2] + (fr(i * 2) - .5) * 14), 10 + fr(i * 4) * 16);
      q.ellipse(mx, my, r, r * (.5 + fr(i * 5) * .8));
    }
  }
  // --- paleochannels: the scars of where the river used to run. Faint, and they cut everything. ---
  const npc = 4 + Math.floor(P.density * 5);
  q.noFill();
  for (let i = 0; i < npc; i++) {
    const off = (fr(i * 13 + 31) - .5) * 2.6;
    q.strokeWeight(Math.max(1, u * (.004 + fr(i) * .008) * P.scale));
    const c = L3(landC, barC, .35);
    q.stroke(c[0], c[1] * .8, Math.max(2, c[2] + 6), 26 + fr(i) * 20);
    q.beginShape();
    for (let yy = -20; yy <= shoreY + 20; yy += 16) {
      const n = yy / Math.max(1, height);
      q.vertex(corr(yy) + (off + Math.sin(n * (4 + i * 2.1) + fr(i + 41) * 6.3) * .8) * halfW(yy) * 1.5, yy);
    }
    q.endShape();
  }
  q.noStroke();

  // --- the braid corridor: wet sand and gravel bars, the bright bed the threads cut through ---
  q.fill(barC[0], barC[1], barC[2], st.ramp ? 60 : 100);
  q.beginShape();
  for (let yy = -20; yy <= shoreY + 30; yy += 12) q.vertex(thread(0, yy) - halfW(yy) * .30, yy);
  for (let yy = shoreY + 30; yy >= -20; yy -= 12) q.vertex(thread(NT - 1, yy) + halfW(yy) * .30, yy);
  q.endShape(q.CLOSE);
  if (!st.ramp) {   // bar bedforms — the sand is combed by the flow
    q.noFill();
    for (let i = 0; i < 130; i++) {
      const yy = fr(i * 3 + 51) * shoreY;
      const xx = thread(Math.floor(fr(i * 3 + 52) * NT), yy) + (fr(i * 3 + 53) - .5) * halfW(yy) * .8;
      q.strokeWeight(Math.max(.5, u * .0012));
      q.stroke(barC[0], barC[1] * 1.2, Math.max(2, barC[2] - 10 + fr(i) * 18), 30);
      q.line(xx - u * .02, yy, xx + u * .02, yy + u * .004);
    }
    q.noStroke();
  }

  // --- the sea / outer estuary ---
  q.fill(seaC[0], seaC[1], seaC[2]); q.rect(0, shoreY, W, H - shoreY + 2);
  if (st.ramp) {   // bathy: depth-banded ramp instead of a single fill
    for (let b = 0; b < 6; b++) {
      const f = b / 6;
      const c = L3(sh(st.chan), sh(st.sea), f);
      q.fill(c[0], c[1], c[2], 78);
      q.beginShape(); q.vertex(-20, H + 20);
      for (let xx = -20; xx <= W + 20; xx += 20)
        q.vertex(xx, shoreY + f * (H - shoreY) * .95 + Math.sin(xx * .006 + b * 1.7 + fr(b) * 6) * u * .02 + u * .02);
      q.vertex(W + 20, H + 20); q.endShape(q.CLOSE);
    }
  }
  // the shoreline is not a line — it is a mudflat fringe
  q.noFill();
  for (let i = 0; i < 3; i++) {
    q.strokeWeight(Math.max(.7, u * .0016));
    q.stroke(barC[0], barC[1], barC[2] - i * 6, 34 - i * 8);
    q.beginShape();
    for (let xx = -20; xx <= W + 20; xx += 14)
      q.vertex(xx, shoreY + i * u * .008 + Math.sin(xx * .009 + fr(i + 61) * 6) * u * .012 + Math.sin(xx * .022 + i) * u * .005);
    q.endShape();
  }
  q.noStroke();

  // --- the threads: the live channels, dark and specular, cut last so they sit on top ---
  S.mouths = [];
  for (let i = 0; i < NT; i++) {
    const wid = u * (.006 + fr(i * 17 + 71) * .014) * P.scale * (1 + (i === Math.floor(NT / 2) ? 1.1 : 0));
    q.noFill();
    for (let pass = 0; pass < 2; pass++) {
      q.strokeWeight(Math.max(1, wid * (pass ? 1 : 1.9)));
      q.stroke(chanC[0], chanC[1] * (pass ? 1 : .7), pass ? chanC[2] : Math.min(99, chanC[2] + 16), pass ? 100 : 26);
      q.beginShape();
      for (let yy = -20; yy <= shoreY + u * .03; yy += 10) q.vertex(thread(i, yy), yy);
      q.endShape();
    }
    S.mouths.push({ x: thread(i, shoreY + u * .02), y: shoreY + u * .02, w: wid });
  }
  q.noStroke();
  if (st.sound) {   // bathy: spot soundings scattered over the water
    for (let i = 0; i < 60; i++) {
      const sx = fr(i * 3 + 81) * W, sy = shoreY + fr(i * 3 + 82) * (H - shoreY);
      q.fill(sh(st.chan)[0], st.chan[1], st.chan[2] + 26, 60);
      q.rect(sx, sy, 2, 2);
    }
  }

  // --- cloud shadows on the ground, and the cloud deck itself: two tileable layers at
  //     different offsets. That parallax IS the altitude cue in a top-down frame. ---
  const shC = sh(st.shadow), cC = sh(st.cloud);
  for (const [gg, col, alp, n] of [[S.shad, shC, 26, 8], [S.cld, cC, 22, 8]]) {
    gg.noStroke();
    for (let i = 0; i < n; i++) {
      const bx = fr(i * 5 + 91) * W, by = fr(i * 5 + 92) * gg.height;
      const bw = u * (.20 + fr(i * 5 + 93) * .55), bhh = u * (.10 + fr(i * 5 + 94) * .3);
      for (let rx = -1; rx <= 1; rx++) for (let kk = 0; kk < 4; kk++) {     // wrap in x only
        gg.fill(col[0], col[1] * (1 - kk * .1), col[2], alp * (1 - kk * .2) * cl);
        gg.ellipse(bx + rx * W, by + kk * bhh * .1, bw * (1 - kk * .13), bhh * (1 - kk * .1));
      }
    }
  }
  S.key = key;
}

// ---------------- act: the tide, over minutes ----------------
const sec = ((Math.floor(K.section) % 8) + 8) % 8;
const ACT = { ebb: { push: .55 + sec * .06, s: 1 }, flood: { push: -.2 - sec * .05, s: .7 }, spate: { push: .9, s: 1.5 + sec * .06 } };
const act = ACT[P.act] || ACT.ebb;
const siltAmt = Math.max(0, Math.min(1.6, si * act.s));

noStroke();
// slow orbital drift of the ground: two incommensurate rates, bounded
const gx = (Math.sin(K.t * .013) * .7 + Math.sin(K.t * .0311 + 1.3) * .3) * u * .010 * P.speed;
const gy = (Math.sin(K.t * .0171 + 2.2) * .7 + Math.sin(K.t * .0413) * .3) * u * .007 * P.speed;
image(S.gnd, gx, gy);

// cloud SHADOWS ride the ground; the cloud DECK rides higher and faster — that offset is the altitude
const WW = S.shad.width;
const scr2 = (g, px, py) => { const ox = ((px % WW) + WW) % WW; image(g, ox - WW, py); image(g, ox, py); };
const cdy = -u * .07 + Math.sin(K.t * .0193) * u * .05 * P.speed;   // bounded: the buffer overhangs, so no seam
scr2(S.shad, -K.t * u * .0095 * P.speed + gx, cdy + gy);

// ---------------- sediment plumes blooming out of every distributary mouth ----------------
const siltC = sh(st.silt), seaC2 = sh(st.sea);
if (S.mouths && !st.ramp) {
  for (let m = 0; m < S.mouths.length; m++) {
    const mo = S.mouths[m];
    // clk baseline carries it; the tide leans it; audio only tops it up
    const pump = .5 + .5 * (Math.sin(K.t * (.23 + m * .031) + m * 2.1) * .6 + Math.sin(K.t * .53 + m) * .3);
    const reach = u * (.10 + .30 * siltAmt) * (.55 + .45 * pump) * (.6 + .4 * en);
    const lean = act.push * u * .07 + Math.sin(K.t * .081 + m) * u * .03;
    for (let j = 7; j >= 0; j--) {
      const f = j / 7;
      const px = mo.x + gx + lean * f + Math.sin(K.t * (.37 + m * .05) + j) * u * .006;
      const py = mo.y + gy + reach * f * .9;
      const c = L3(siltC, seaC2, f * .55);
      fill(c[0], c[1] * (1 - f * .2), c[2], (7 + 16 * siltAmt) * (1 - f * .55) * (.4 + .6 * en));
      ellipse(px, py, reach * (.5 + f * 1.5) + mo.w * 4, reach * (.35 + f * 1.1));
    }
  }
}

// ---------------- specular glint on the open water ----------------
const glC = sh(st.glint);
if (!st.ramp) {
  blendMode(ADD);
  const ng2 = Math.floor(12 + P.density * 20);
  for (let i = 0; i < ng2; i++) {
    const gx2 = fr(i * 7 + 401) * width, gy2 = shoreY + fr(i * 7 + 402) * (height - shoreY);
    const sm = .5 + .5 * (Math.sin(K.t * (.61 + i * .015) + i) * .55 + Math.sin(K.t * 1.43 + i * 2.1) * .3 + Math.sin(K.t * 2.29 + i) * .15);
    const gain = (.3 + .7 * en) * (.35 + .65 * sm) + A.treble * .18;
    fill(glC[0], glC[1], glC[2], (4 + 20 * gain));
    ellipse(gx2 + gx + Math.sin(K.t * .29 + i) * u * .01, gy2 + gy, u * (.03 + .08 * sm), u * .008);
  }
  blendMode(BLEND);
}

// the deck: white cloud, offset from its own shadow. Never a flash — it drifts.
scr2(S.cld, -K.t * u * .0122 * P.speed, cdy * .8 + Math.sin(K.t * .0271 + 1.1) * u * .012);

// ---------------- sensor grain + frame ----------------
if (st.grain > 6) {
  const ng = Math.floor(st.grain * 6);
  for (let i = 0; i < ng; i++) {
    const px = ((fr(i * 3 + 501) * width) + Math.sin(K.t * .012 + i) * u * .003 + width) % width;
    const py = fr(i * 3 + 502) * height;
    fill(hw(st.land[0] + ho), st.land[1] * .5, fr(i * 3 + 503) > .5 ? 94 : 5, 3 + fr(i) * 6);
    rect(px, py, u * .0016, u * .0016);
  }
}
for (let i = 0; i < 5; i++) {
  noFill(); strokeWeight(u * .055);
  stroke(hw(st.chan[0] + ho), st.chan[1], st.ramp ? 80 : 7, 16 * (1 - i * .17));
  rect(-u * .03 + i * u * .03, -u * .03 + i * u * .03, width + u * .06 - i * u * .06, height + u * .06 - i * u * .06);
}
noStroke();

if (P.alpha < 1) { fill(hw(st.chan[0] + ho), st.chan[1] * .5, 5, (1 - P.alpha) * 100); rect(0, 0, width, height); }
blendMode(BLEND);
drawingContext.shadowBlur = 0;
